"""Searching helpers."""


def binary_search(items, target):
    """Index of target in the sorted list items, or -1 if it is not there."""
    lo, hi = 0, len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

files.tests/test_sorting.py:
from sortkit.sorting import merge_sort, quick_sort


def test_merge_sort_basic():
    assert merge_sort([3, 1, 2]) == [1, 2, 3]


def test_merge_sort_empty_and_single():
    assert merge_sort([]) == []
    assert merge_sort([7]) == [7]


def test_merge_sort_duplicates():
    assert merge_sort([5, 1, 5, 3, 1]) == [1, 1, 3, 5, 5]


def test_quick_sort_basic():
    assert quick_sort([3, 1, 2]) == [1, 2, 3]


def test_quick_sort_duplicates():
    assert quick_sort([2, 2, 1]) == [1, 2, 2]

